1	// Shared VPS order core — used by the wallet flow (lib/actions.ts orderServer),
2	// the direct-pay flow (payAndDeploy), and the Stripe confirm route so a paid
3	// checkout can provision immediately. Plain server module (not "use server").
4	import { z } from "zod";
5	import type { User } from "@prisma/client";
6	import { db } from "./db";
7	import { debitWallet, InsufficientBalanceError } from "./wallet";
8	import { vpsTerm, vpsTermPriceCents, addMonths } from "./billing-terms";
9	import { dedicatedIpMonthlyCents } from "./dedicated-ip";
10	import { capacityCheck, diskCapacityCheck } from "./capacity";
11	import { invoiceCreateData } from "./invoices";
12	import { maybeRewardReferral } from "./actions-growth";
13	import { currentPromo } from "./promotions";
14	import {
15	  claimFirstMonthFree,
16	  firstMonthFreeEnabled,
17	  firstMonthFreeAppliesTo,
18	  setPromoOrderRef,
19	} from "./promo-redemption";
20	import { extraDiskPerGbCents } from "./disk-expand";
21	import {
22	  EXTRA_DISK_MAX_ADD_GB,
23	  EXTRA_DISK_MAX_TOTAL_GB,
24	  effectiveDiskGB,
25	  extraDiskCentsAt,
26	  extraDiskLabel,
27	  normalizeExtraDiskGB,
28	} from "./extra-disk";
29	import { getSettingBool } from "./settings";
30	import { couponOrderDiscountCents } from "./coupon-order";
31	import { backupPlusMonthlyCents } from "./backup-upgrade";
32	import {
33	  type BackupTier,
34	  backupTierMonthlyCents,
35	  backupTierSpec,
36	  normalizeBackupTier,
37	} from "./backup-tiers";
38	
39	export class OrderError extends Error {}
40	
41	export const orderSchema = z.object({
42	  planId: z.string().min(1),
43	  osTemplateId: z.string().min(1),
44	  hostname: z
45	    .string()
46	    .min(3)
47	    .max(40)
48	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
49	  // Deploy-time extra-disk upsell. Coerced + step-normalized by
50	  // normalizeExtraDiskGB before it reaches here, so this is a range guard only.
51	  extraDiskGB: z.coerce.number().int().min(0).max(EXTRA_DISK_MAX_ADD_GB).optional(),
52	  // Optional checkout promo code. Uppercased + trimmed; the discount + all
53	  // redemption guards live in orderQuote / placeOrder.
54	  couponCode: z.string().trim().max(32).optional(),
55	});
56	
57	export type OrderIntent = {
58	  planId: string;
59	  osTemplateId: string;
60	  hostname: string;
61	  nodeId?: string;
62	  addonMalware?: boolean;
63	  addonBackup?: boolean;
64	  addonDocker?: boolean;
65	  termMonths?: number;
66	  dedicatedIp?: boolean;
67	  sshPublicKey?: string;
68	  sshKeyName?: string;
69	  free?: boolean;
70	  /**
71	   * Extra root-disk GB bought at deploy time, ON TOP of the plan's diskGB. The VM
72	   * is provisioned at plan.diskGB + extraDiskGB (worker/index.ts provision), so no
73	   * post-deploy expansion job is needed. Permanent — never shrinks.
74	   */
75	  extraDiskGB?: number;
76	  /** Checkout promo code (e.g. a "one free month" coupon), uppercased. */
77	  couponCode?: string;
78	  /**
79	   * Paid backup RETENTION tier bought at deploy time. FREE (included) or PLUS
80	   * (keep 7, priced monthly like the other add-ons). Round-tripped through Stripe
81	   * metadata, so it stays a tiny string.
82	   */
83	  backupTier?: BackupTier;
84	};
85	
86	/**
87	 * The price an order was SOLD at: the total, and the promo rate that produced it.
88	 * Fixed ONCE — before any money moves — and carried to the moment it is charged.
89	 *
90	 * REAL INCIDENT (2026-07-26 customer-journey rehearsal, H2). The card-paid deploy
91	 * path quoted a total, charged the CARD its share of that total at Stripe, and
92	 * then — on the confirm redirect, minutes or hours later — re-ran `orderQuote`
93	 * and debited whatever came back. That re-run includes `currentPromo(new Date())`,
94	 * and lib/promotions.ts always has an active sale that rotates by calendar date,
95	 * so a rotation between "customer clicked Deploy" and "customer came back from
96	 * Stripe" re-priced the order AFTER the card had cleared and took the difference
97	 * out of the wallet with no new consent. With no balance to take it from, the
98	 * payment was captured and no server was created.
99	 *
100	 * `lib/resize.ts` and `lib/disk-expand.ts` already carried the amount through
101	 * Stripe metadata for exactly this reason; the order path was the one that
102	 * re-derived it. Same rule as lib/renewal-quote.ts and lib/proration.ts: a figure
103	 * the customer was shown is not recomputed later, it is carried.
104	 *
105	 * `promoPercent` and `promoName` travel WITH the total because they are not
106	 * decoration. `Server.termPromoPercent` records the rate a term was actually sold
107	 * at (every later proration prices against it), and the promo name is the ledger
108	 * and invoice text the customer reads. Honouring a 30%-off price while stamping
109	 * today's 15% would hand every later proration the wrong basis and print a
110	 * discount on the invoice that does not match the money taken.
111	 */
112	export type OrderPrice = {
113	  /** Total to charge, in cents — the figure the customer consented to. */
114	  chargeCents: number;
115	  /** Promo rate (%) that produced it; persisted as `Server.termPromoPercent`. */
116	  promoPercent: number;
117	  /** Promo name for the ledger / invoice line, e.g. "Summer Sale". */
118	  promoName: string;
119	};
120	
121	/** The sold price implied by a quote — the ONE place a quote becomes a price. */
122	export function orderPriceOf(quote: {
123	  chargeCents: number;
124	  promo: { discountPercent: number; name: string };
125	}): OrderPrice {
126	  return {
127	    chargeCents: quote.chargeCents,
128	    promoPercent: quote.promo.discountPercent,
129	    promoName: quote.promo.name,
130	  };
131	}
132	
133	/**
134	 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
135	 * well-formed: a half-parsed price would be worse than no price at all, because
136	 * the caller's fallback (re-quote) is at least internally consistent.
137	 */
138	export function parseOrderPrice(raw: unknown): OrderPrice | null {
139	  let obj: unknown = raw;
140	  if (typeof raw === "string") {
141	    try {
142	      obj = JSON.parse(raw);
143	    } catch {
144	      return null;
145	    }
146	  }
147	  if (!obj || typeof obj !== "object") return null;
148	  const { chargeCents, promoPercent, promoName } = obj as Record<string, unknown>;
149	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
150	  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
151	  if (promoPercent < 0 || promoPercent > 100) return null;
152	  return { chargeCents, promoPercent, promoName: typeof promoName === "string" ? promoName : "" };
153	}
154	
155	/** Extract a plain OrderIntent from a deploy form. */
156	export function intentFromFormData(formData: FormData): OrderIntent {
157	  return {
158	    planId: String(formData.get("planId") ?? ""),
159	    osTemplateId: String(formData.get("osTemplateId") ?? ""),
160	    hostname: String(formData.get("hostname") ?? ""),
161	    nodeId: String(formData.get("nodeId") ?? "") || undefined,
162	    addonMalware: formData.get("addon_malware") === "1",
163	    addonBackup: formData.get("addon_backup") === "1",
164	    addonDocker: formData.get("addon_docker") === "1",
165	    termMonths: Number(formData.get("termMonths") ?? 1),
166	    dedicatedIp: formData.get("dedicatedIp") === "1",
167	    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
168	    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
169	    free: formData.get("free") === "1",
170	    // Rounded DOWN to a purchasable step — a malformed value can only ever cost
171	    // the customer less, never more. Left UNDEFINED (not 0) when nothing was
172	    // bought so it drops out of JSON.stringify: the intent is round-tripped
173	    // through Stripe metadata, which is capped at 500 chars (lib/stripe.ts
174	    // createOrderCheckout), and every byte of headroom matters there.
175	    extraDiskGB: normalizeExtraDiskGB(formData.get("extraDiskGB")) || undefined,
176	    couponCode: String(formData.get("couponCode") ?? "").trim().toUpperCase() || undefined,
177	    // Only PLUS is a paid choice; left UNDEFINED for FREE (the included tier) so it
178	    // drops out of the Stripe-metadata JSON round-trip, like extraDiskGB. orderQuote
179	    // re-normalizes undefined back to FREE.
180	    backupTier: normalizeBackupTier(formData.get("backup_tier")) === "PLUS" ? "PLUS" : undefined,
181	  };
182	}
183	
184	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
185	async function scheduleNode(planRamMB: number) {
186	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
187	  if (nodes.length === 0) return null;
188	  const loads = await Promise.all(
189	    nodes.map(async (n) => {
190	      const agg = await db.server.findMany({
191	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
192	        select: { plan: { select: { ramMB: true } } },
193	      });
194	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
195	      return { node: n, free: n.capacityRamMB - used };
196	    }),
197	  );
198	  loads.sort((a, b) => b.free - a.free);
199	  return loads[0].node;
200	}
201	
202	/** Validate + price an order without placing it. Throws OrderError on any problem. */
203	export async function orderQuote(intent: OrderIntent, opts?: { suppressPromo?: boolean }) {
204	  const parsed = orderSchema.safeParse(intent);
205	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
206	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
207	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
208	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
209	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
210	    throw new OrderError(
211	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
212	    );
213	  }
214	  const term = vpsTerm(Number(intent.termMonths ?? 1));
215	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
216	
217	  // Extra root disk, priced per GB/month and multiplied over the term exactly
218	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
219	  // promo — the customer pays the same $/GB whichever term they pick, and renews
220	  // at the same rate). Growth is one-way: this is permanent for the server.
221	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
222	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
223	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
224	  const extraDiskCents = extraDiskMonthlyCents * term.months;
225	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
226	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
227	  }
228	
229	  // Paid backup RETENTION tier, priced per month and multiplied over the term
230	  // exactly like the extra-disk add-on (NOT promo-discounted — the customer pays
231	  // the same $/mo whichever term or promo, and renews at the same rate through
232	  // renewalCharge). Only PLUS is paid; FREE (the included tier) is $0.
233	  const backupTier = normalizeBackupTier(intent.backupTier);
234	  const backupMonthlyCents =
235	    backupTier === "FREE" ? 0 : backupTierMonthlyCents(backupTier, await backupPlusMonthlyCents());
236	  const backupCents = backupMonthlyCents * term.months;
237	
238	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
239	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
240	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
241	  // real renewal price and this discounted value is the real first-term price.
242	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
243	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
244	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
245	  const promo = currentPromo(new Date());
246	  // The promo is now MANAGED: the owner can switch it off, and every claim is
247	  // capped 1/account + 1/IP (lib/promo-redemption.ts). When the toggle is off the
248	  // quote shows — and placeOrder charges — the full price, so display === charged
249	  // on the disabled path. When it is on, the quote shows the first-month-free
250	  // price and the atomic claim in placeOrder's tx is the final arbiter of whether
251	  // the credit is actually granted (a lost race there is charged full).
252	  // `suppressPromo` prices this quote at FULL price even when the promo is on —
253	  // the card path uses it to re-quote for a customer who has already redeemed
254	  // (per-account/IP), so their Stripe leg and stamped total are full, not free.
255	  // The first-month-free promo is scoped to Shared Web Hosting only — VPS always
256	  // bills full. `firstMonthFreeAppliesTo("VPS")` is false, so promoEnabled is
257	  // false here and planFirstTermCents falls through to the regular term total.
258	  const promoEnabled =
259	    firstMonthFreeAppliesTo("VPS") && !opts?.suppressPromo && (await firstMonthFreeEnabled());
260	  // First-month-free must credit exactly ONE MONTH — not zero a multi-month term.
261	  // A naive promoPriceCents(termTotal) at 100% off would give a 36-month term 3
262	  // YEARS free. So we subtract one month of the plan's rate from the term total.
263	  // For a 1-month term this lands at $0 (genuinely first month free); for a 12/24/
264	  // 36-month term the customer pays the term minus one month. Renewals bill the
265	  // full vpsTermPriceCents unchanged (worker/billing.ts) — displayed === charged.
266	  const planFirstTermCents =
267	    promoEnabled && promo.firstMonthFree
268	      ? Math.max(0, regularPlanCents - plan.priceCents)
269	      : regularPlanCents;
270	  // The one-month credit this order gets IF the atomic claim succeeds. 0 when the
271	  // promo is off. placeOrder adds it back to charge full when the claim is lost.
272	  const promoCreditCents = regularPlanCents - planFirstTermCents;
273	
274	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
275	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
276	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
277	  // so the deploy preview can show it; the redemption itself (count + per-user +
278	  // per-IP guards) is claimed atomically in placeOrder.
279	  let couponId: string | null = null;
280	  let couponDiscountCents = 0;
281	  let couponLabel = "";
282	  let couponError = "";
283	  let couponMaxRedemptions: number | null = null;
284	  let couponFirstTimeOnly = false;
285	  const code = (intent.couponCode ?? "").trim().toUpperCase();
286	  if (code) {
287	    if (!(await getSettingBool("coupons_enabled", true))) {
288	      couponError = "Promo codes are currently disabled.";
289	    } else {
290	      const coupon = await db.coupon.findUnique({ where: { code } });
291	      if (!coupon) {
292	        couponError = "That code isn’t valid.";
293	      } else {
294	        const verdict = couponOrderDiscountCents(
295	          {
296	            kind: coupon.kind,
297	            value: coupon.value,
298	            serviceKind: coupon.serviceKind,
299	            planSlug: coupon.planSlug,
300	            maxTermMonths: coupon.maxTermMonths,
301	            active: coupon.active,
302	            expiresAt: coupon.expiresAt,
303	            maxRedemptions: coupon.maxRedemptions,
304	            timesRedeemed: coupon.timesRedeemed,
305	            minAmountCents: coupon.minAmountCents,
306	          },
307	          {
308	            serviceKind: "VPS",
309	            planSlug: plan.slug,
310	            planMonthlyCents: plan.priceCents,
311	            termMonths: term.months,
312	            planChargeCents: planFirstTermCents,
313	          },
314	          new Date(),
315	        );
316	        if (verdict.ok) {
317	          couponId = coupon.id;
318	          couponDiscountCents = verdict.discountCents;
319	          couponLabel = verdict.label;
320	          couponMaxRedemptions = coupon.maxRedemptions;
321	          couponFirstTimeOnly = coupon.firstTimeOnly;
322	        } else {
323	          couponError = verdict.error;
324	        }
325	      }
326	    }
327	  }
328	
329	  const chargeCents = planFirstTermCents - couponDiscountCents + ipCents + extraDiskCents + backupCents;
330	  return {
331	    plan,
332	    os,
333	    term,
334	    chargeCents,
335	    promo,
336	    promoCreditCents,
337	    regularPlanCents,
338	    extraDiskGB,
339	    extraDiskMonthlyCents,
340	    extraDiskCents,
341	    backupTier,
342	    backupMonthlyCents,
343	    backupCents,
344	    couponId,
345	    couponDiscountCents,
346	    couponLabel,
347	    couponError,
348	    couponMaxRedemptions,
349	    couponFirstTimeOnly,
350	  };
351	}
352	
353	/**
354	 * Place an order: validate, charge the wallet (unless a free admin grant),
355	 * create the Server + PROVISION job. Returns the new server id. Does NOT
356	 * redirect. Callers must ensure funds exist (or pass free) — this still
357	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
358	 *
359	 * `sold` overrides the recomputed price with the one the order was actually SOLD
360	 * at — the card-paid path passes the figure stamped on the Checkout session
361	 * BEFORE the card was charged, so the confirm redirect settles the price the
362	 * customer consented to instead of re-pricing against whatever promo is running
363	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
364	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
365	 * quote, which it computed moments ago in the same request. See OrderPrice.
366	 */
367	/**
368	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
369	 * any failure so nothing partial survives. Kept separate from the order tx so a
370	 * wallet order can surface the failure before any money moves, and a card order
371	 * (already paid) can swallow it without stranding the paid provision.
372	 *
373	 * Guards, all enforced here: first-time-only (no prior paid server), the
374	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
375	 * (the two @@unique constraints on CouponRedemption).
376	 */
377	async function claimOrderCoupon(opts: {
378	  couponId: string;
379	  maxRedemptions: number | null;
380	  firstTimeOnly: boolean;
381	  userId: string;
382	  ipHash: string | null;
383	  amountCents: number;
384	}): Promise<void> {
385	  await db.$transaction(async (tx) => {
386	    if (opts.firstTimeOnly) {
387	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
388	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
389	    }
390	    // Atomic conditional increment — the only thing between the last free slot and
391	    // an over-redemption when two orders race for it.
392	    const claim = await tx.coupon.updateMany({
393	      where:
394	        opts.maxRedemptions === null
395	          ? { id: opts.couponId, active: true }
396	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
397	      data: { timesRedeemed: { increment: 1 } },
398	    });
399	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
400	    try {
401	      await tx.couponRedemption.create({
402	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
403	      });
404	    } catch {
405	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
406	      // this person. Throwing rolls back the increment above with it.
407	      throw new OrderError("You’ve already used this code.");
408	    }
409	  });
410	}
411	
412	/**
413	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
414	 *
415	 * The card leg discounts `cardCents` up front and only settles the redemption
416	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
417	 * paid provision is never stranded. Without this pre-check, a customer who has
418	 * already used a one-per-person code (or isn't first-time) still gets the
419	 * discounted card charge and the swallow hides it. So before we send them to
420	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
421	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
422	 * (a race could still lose the atomic claim at settle time — that path stays
423	 * swallowed by design), but it closes the everyday bypass.
424	 */
425	export async function orderCouponClaimable(opts: {
426	  couponId: string;
427	  firstTimeOnly: boolean;
428	  maxRedemptions: number | null;
429	  userId: string;
430	  ipHash: string | null;
431	}): Promise<{ ok: true } | { ok: false; error: string }> {
432	  if (opts.firstTimeOnly) {
433	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
434	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
435	  }
436	  const byUser = await db.couponRedemption.findUnique({
437	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
438	  });
439	  if (byUser) return { ok: false, error: "You’ve already used this code." };
440	  if (opts.ipHash) {
441	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
442	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
443	  }
444	  if (opts.maxRedemptions !== null) {
445	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
446	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
447	  }
448	  return { ok: true };
449	}
450	
451	export async function placeOrder(
452	  user: User,
453	  intent: OrderIntent,
454	  sold?: OrderPrice | null,
455	  opts?: { ipHash?: string | null; campaign?: string },
456	): Promise<string> {
457	  const quote = await orderQuote(intent);
458	  const { plan, os, term, promo, promoCreditCents, extraDiskGB, extraDiskMonthlyCents, extraDiskCents, backupTier, backupMonthlyCents, backupCents } = quote;
459	  // Everything below bills off THESE three, never off `quote.chargeCents` /
460	  // `promo` directly: when a sold price is present it is the whole truth about
461	  // what this order costs and what rate it was sold at.
462	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
463	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
464	  const promoName = sold?.promoName || promo.name;
465	  // Note the intro discount on the billing document (first term only; renews full).
466	  const promoNote = promoPercent > 0 ? ` · ${promoName} ${promoPercent}% off first term` : "";
467	
468	  // Managed first-month-free: is the price we're settling one that carries the
469	  // credit? Wallet path prices off the fresh quote (promoCreditCents), card path
470	  // off the sold rate. Only then do we contend for the atomic claim below.
471	  const promoApplied = sold ? sold.promoPercent > 0 : promoCreditCents > 0;
472	
473	  const cap = await capacityCheck(plan.id);
474	  if (!cap.ok) throw new OrderError(cap.reason);
475	
476	  let nodeId: string | null = null;
477	  if (intent.nodeId) {
478	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
479	    if (!n) throw new OrderError("Selected location is not available.");
480	    nodeId = n.id;
481	  } else {
