1	/**
2	 * Billing term definitions + discount math, shared by ordering, renewal,
3	 * the deploy wizard, invoices and the domain flow. Discounts are the platform's
4	 * promo (longer commitment = cheaper); tune here (or later via admin Settings).
5	 */
6	
7	export type VpsTerm = { months: number; label: string; short: string; discountPct: number };
8	
9	export const VPS_TERMS: VpsTerm[] = [
10	  { months: 1, label: "Monthly", short: "1 mo", discountPct: 0 },
11	  { months: 12, label: "Annual", short: "1 yr", discountPct: 10 },
12	  { months: 24, label: "Biennial", short: "2 yr", discountPct: 15 },
13	  { months: 36, label: "Triennial", short: "3 yr", discountPct: 20 },
14	];
15	
16	export function vpsTerm(months: number): VpsTerm {
17	  return VPS_TERMS.find((t) => t.months === months) ?? VPS_TERMS[0];
18	}
19	
20	/** Total charge (cents) for a plan over a term, discount applied. */
21	export function vpsTermPriceCents(monthlyCents: number, months: number): number {
22	  const t = vpsTerm(months);
23	  return Math.round(monthlyCents * months * (1 - t.discountPct / 100));
24	}
25	
26	/**
27	 * Effective monthly-equivalent price after the term discount (for "$/mo" display).
28	 *
29	 * `months <= 0` returns the undiscounted monthly price rather than dividing by it.
30	 * This is not display hygiene — it is a money guard. `prorateDeltaCents`
31	 * (lib/proration.ts) prices BOTH halves of every upgrade and downgrade credit
32	 * through this function using `Server.termMonths`, and a 0 there made the division
33	 * `0 / 0` → NaN, which sails through `Math.round`, through `Math.max(0, delta)`
34	 * (NaN is not > 0, so the clamp returns NaN, not 0) and into `debitWallet` as the
35	 * amount to take. The result is a charge that either explodes at the database or,
36	 * on the credit side, writes NaN where a customer's balance used to be. The column
37	 * defaults to 1 and every writer clamps to >= 1 today, so this is a latch, not a
38	 * live bug — but a shared money function must not have a NaN in it.
39	 */
40	export function vpsEffectiveMonthly(monthlyCents: number, months: number): number {
41	  if (!Number.isFinite(months) || months <= 0) return Math.round(monthlyCents);
42	  return Math.round(vpsTermPriceCents(monthlyCents, months) / months);
43	}
44	
45	export type DomainTerm = { years: number; label: string; discountPct: number };
46	
47	export const DOMAIN_TERMS: DomainTerm[] = [
48	  { years: 1, label: "1 year", discountPct: 0 },
49	  { years: 2, label: "2 years", discountPct: 5 },
50	  { years: 3, label: "3 years", discountPct: 10 },
51	];
52	
53	export function domainTerm(years: number): DomainTerm {
54	  return DOMAIN_TERMS.find((t) => t.years === years) ?? DOMAIN_TERMS[0];
55	}
56	
57	/** Total charge (cents) for a domain over N years, discount applied. */
58	export function domainTermPriceCents(perYearCents: number, years: number): number {
59	  const t = domainTerm(years);
60	  return Math.round(perYearCents * years * (1 - t.discountPct / 100));
61	}
62	
63	/** Add whole months to a date (UTC-safe enough for billing windows). */
64	export function addMonths(from: Date, months: number): Date {
65	  const d = new Date(from);
66	  d.setMonth(d.getMonth() + months);
67	  return d;
68	}
