1	import { vpsTerm, vpsTermPriceCents } from "./billing-terms";
2	import { extraDiskCentsAt } from "./extra-disk";
3	import { type BackupTier, backupTierMonthlyCents } from "./backup-tiers";
4	
5	/**
6	 * What one renewal costs — the SINGLE definition, used by every path that quotes
7	 * or charges one: the automatic sweep in worker/billing.ts, the saved-card path,
8	 * the "Renew now" button, the server page and the deploy wizard's term cards.
9	 *
10	 * WHY IT LIVES IN ITS OWN FILE. It used to sit in lib/stripe-cards.ts, which
11	 * imports the Stripe SDK and (transitively) nodemailer. The moment a CLIENT
12	 * component — the deploy wizard — needed the renewal price, that import chain
13	 * dragged `nodemailer/lib/dkim` into the browser bundle and the build failed with
14	 * "Can't resolve 'fs'". The pricing rule is pure arithmetic and has no business
15	 * carrying a mail transport with it, so it lives here with only the two tiny
16	 * modules it genuinely needs. lib/stripe-cards.ts re-exports it, so no server-side
17	 * caller had to change.
18	 *
19	 * The rule this file exists to enforce: there is ONE renewal formula. Two
20	 * incidents in one day came from a second copy — first a button that hardcoded
21	 * "+30 days" and the monthly price while the action charged a full term ($8.99
22	 * shown, $97.09 taken), then the shared quote written to fix it, which computed
23	 * from `plan.priceCents` and so ignored `gamePlan` and would have billed a $4.99
24	 * game server at its $8.99 base plan. Do not add a second formula.
25	 */
26	export type RenewalCharge = {
27	  months: number;
28	  totalCents: number;
29	  /** The extra-root-disk portion, which gets its own invoice line. */
30	  extraDiskCents: number;
31	  extraDiskMonthlyCents: number;
32	  /** The paid backup-tier portion (Plus retention), which gets its own invoice line. */
33	  backupCents: number;
34	  backupMonthlyCents: number;
35	  /** Human label for the invoice / receipt ("Nebula VPS" or the game plan name). */
36	  label: string;
37	};
38	
39	export type PricedServer = {
40	  termMonths: number;
41	  extraDiskGB: number;
42	  plan: { name: string; priceCents: number };
43	  gamePlan: { name: string; priceCents: number; termMonths: number } | null;
44	  dedicatedIp: unknown | null;
45	  /** Paid backup retention tier. A full Server row supplies it; synthetic callers must pass it. */
46	  backupTier: BackupTier;
47	};
48	
49	export function renewalCharge(
50	  server: PricedServer,
51	  prices: { ipMonthlyCents: number; extraDiskPerGbCents: number; backupPlusCents: number },
52	): RenewalCharge {
53	  const isGame = !!server.gamePlan;
54	  const months = isGame ? server.gamePlan!.termMonths : vpsTerm(server.termMonths).months;
55	  // Extra root disk is billed EVERY cycle at the current per-GB price. Game plans
56	  // are a flat all-in price and never carry the add-on lines.
57	  const extraDiskMonthlyCents = isGame ? 0 : extraDiskCentsAt(server.extraDiskGB, prices.extraDiskPerGbCents);
58	  const extraDiskCents = extraDiskMonthlyCents * months;
59	  // Paid backup retention (Plus) rides alongside extra disk: billed every cycle at
60	  // the current admin price, and — like every add-on line — NOT carried by a game
61	  // plan (renewalCharge's game branch is flat all-in, so game servers are never
62	  // sold a paid backup tier; see lib/backup-upgrade.ts's game guard).
63	  const backupMonthlyCents = isGame ? 0 : backupTierMonthlyCents(server.backupTier, prices.backupPlusCents);
64	  const backupCents = backupMonthlyCents * months;
65	  const totalCents = isGame
66	    ? server.gamePlan!.priceCents
67	    : vpsTermPriceCents(server.plan.priceCents, months) +
68	      // Bill the IP surcharge only when the server ACTUALLY holds a dedicated IP,
69	      // not off the intent flag — a NAT-fallback server must never be charged for
70	      // an IP it never received.
71	      (server.dedicatedIp ? prices.ipMonthlyCents * months : 0) +
72	      extraDiskCents +
73	      backupCents;
74	  return {
75	    months,
76	    totalCents,
77	    extraDiskCents,
78	    extraDiskMonthlyCents,
79	    backupCents,
80	    backupMonthlyCents,
81	    label: isGame ? server.gamePlan!.name : `${server.plan.name} VPS`,
82	  };
83	}
