// Typed access layer over the key/value `Setting` store (db.setting).
//
// Plain (non-"use server") module so it can export the SETTINGS_DEFAULTS map,
// types and pure helpers alongside the async DB getters/setters. Import it from
// server components, server actions and the worker. Do NOT import from client
// components.
//
// Every admin-editable knob lives here with a default, so reads are total: a key
// that has never been written falls back to its SETTINGS_DEFAULTS value. Booleans
// are stored as the strings "true"/"false"; money is stored in cents; percents as
// plain numbers (e.g. "8.5" = 8.5%).

import { db } from "./db";
import { VPS_TERMS } from "./billing-terms";

export const SETTINGS_DEFAULTS = {
  // --- General / Branding ---
  //
  // Every default in this block is the string that was previously HARDCODED at the
  // render site it now feeds. That matters: `getSetting` falls back to these, so a
  // platform with an empty `Setting` table must render exactly what it rendered
  // before the wiring landed. A default of "" here would have blanked the footer
  // tagline and produced an empty `mailto:` on /contact the moment these keys were
  // read for the first time.
  brand_name: "Nxeon",
  // Verbatim the copy that used to be inline in components/marketing/MarketingFooter.tsx.
  // The footer is this key's only consumer, so the panel now previews what actually ships.
  brand_tagline:
    "Premium NVMe cloud VPS hosting, provisioned in seconds. Built for developers, teams, and everything you ship.",
  // Was "". The contact page advertises this address in three places and every one of
  // them hardcoded it, so the panel showed a blank support email while the marketing
  // site published a real one — and reading the blank key would have shipped
  // `mailto:` with no recipient.
  support_email: "support@nxeon.cloud",
  // Blank is legitimate for these two: `renderInvoiceHTML` omits the seller block
  // entirely when they are unset rather than printing an empty "From" address.
  company_legal_name: "",
  company_address: "",
  social_twitter: "",
  social_github: "",
  social_discord: "",
  social_linkedin: "",
  footer_text: "",
  // Raw provider <script> body injected by components/marketing/LiveChat.tsx.
  livechat_snippet: "",
  // --- External review profiles (Reviews engine) ---
  //
  // Public URLs of our third-party review profiles. Managed on /admin/reviews.
  // They do two jobs: they turn the homepage review badges into real links (a
  // badge with no configured URL is not shown), and the post-purchase review-
  // request email only sends when at least one is set — so we never ask a
  // customer to "leave a review" with nowhere to send them. Blank = not set up.
  review_url_trustpilot: "",
  review_url_hostadvice: "",
  review_url_google: "",
  // Business-email DNS shown to customers (MX host + SPF include).
  //
  // These MUST match what mail actually runs on. They previously read
  // `mx.nxeon.email` / `_spf.nxeon.email` — a domain not used anywhere in this
  // platform — while `lib/actions-email-hosting.ts` hardcodes `mail.nxeon.cloud`
  // and `nxeon.cloud`, which is what real customer DNS uses and what an external
  // verifier confirmed working (revsports.ca: MX -> mail.nxeon.cloud,
  // SPF -> "v=spf1 include:nxeon.cloud ~all", DKIM/SPF/iprev all passing).
  //
  // Nothing read these keys, so the wrong values were harmless — but they were a
  // loaded trap: wiring the setting through without correcting it first would have
  // handed every business-email customer non-working DNS records and made the
  // deliverability checker fail correct setups. Corrected here so the wiring is
  // safe whenever someone does it.
  email_mx_host: "mail.nxeon.cloud",
  email_spf_include: "nxeon.cloud",

  // --- Billing ---
  currency: "USD",
  tax_percent: "0",
  min_topup_cents: "500",
  // Stored as a NUMBER OF MONTHS, and it must be one of `VPS_TERMS` (1/12/24/36).
  //
  // It used to be the enum "monthly" | "quarterly" | "annual", which nothing read —
  // and could not have been read: the platform sells no quarterly term at all, and
  // the enum had no way to express biennial or triennial. Wiring that vocabulary into
  // the deploy wizard would have meant an operator selecting "Quarterly", seeing
  // "Saved.", and the wizard silently pre-selecting monthly instead. Months are the
  // unit every charge path already speaks (`termMonths` on the order form,
  // `vpsTermPriceCents`, `addMonths`), so the setting now speaks it too and
  // `defaultTermMonths()` refuses anything the billing catalogue cannot honour.
  default_term: "1",
  invoice_prefix: "INV-",
  dunning_grace_days: "3",
  dunning_warn_days: "7",
  dunning_terminate_days: "14",
  auto_suspend_enabled: "true",
  /**
   * Master switch for the email-verification purchase gate
   * (lib/email-verification.ts). Deliberately OFF by default.
   *
   * WHY OFF. The gate makes "our email was delivered" a hard prerequisite for
   * taking money. As of 2026-07-26 this platform's own DKIM record
   * (`dkim._domainkey.nxeon.cloud`) is MISSING — verified NXDOMAIN against a
   * public resolver — so every transactional email it sends is unsigned and
   * materially more likely to be filtered. Arming the gate in that state means a
   * new customer's verification link lands in spam and they simply cannot buy,
   * with no error anyone would ever see. A sale lost in silence is worse than the
   * unverified signups the gate exists to prevent.
   *
   * `emailVerificationError` already fails open when there is no mail transport
   * at all. This is the same reasoning one step out: a transport that sends mail
