/** OVH failover gateway = the host's /24 gateway (…​.254). */
export function ovhGateway(): string {
  const ip = process.env.PUBLIC_IP ?? "51.79.162.96";
  const parts = ip.split(".");
  return `${parts[0]}.${parts[1]}.${parts[2]}.254`;
}

/**
 * Pull additional/failover IPv4 addresses routed to our server from OVH and
 * upsert them into the pool. The host's own primary IP is never poolable.
 */
export async function syncDedicatedIpPool(): Promise<{ imported: number; total: number }> {
  if (SANDBOX) return { imported: 0, total: 0 };
  if (!ovhConfigured()) return { imported: 0, total: 0 };
  const primary = process.env.PUBLIC_IP;
  const blocks: string[] = await ovhApi.ips();
  let imported = 0;
  for (const block of blocks) {
    if (block.includes(":")) continue; // IPv6 handled separately
    let info: any;
    try {
      info = await ovhApi.ipInfo(block);
    } catch {
      continue;
    }
    if (info?.routedTo?.serviceName !== SERVER) continue;
    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
    // A /32 block is a single usable IP == the block minus the mask.
    const address = block.split("/")[0];
    if (address === primary) continue;
    const existing = await db.dedicatedIp.findUnique({ where: { address } });
    if (!existing) {
      await db.dedicatedIp.create({ data: { address, ovhBlock: block, status: "FREE" } });
      imported++;
    }
  }
  const total = await db.dedicatedIp.count();
  return { imported, total };
}

export async function freeCount(): Promise<number> {
  return db.dedicatedIp.count({ where: { status: "FREE" } });
}

/** Find the OVH Virtual MAC currently bound to an IP, if any. */
async function findVirtualMacForIp(address: string): Promise<string | null> {
  const macs: string[] = await ovh("GET", `/dedicated/server/${SERVER}/virtualMac`).catch(() => []);
  for (const m of macs) {
    const ips: string[] = await ovh(
      "GET",
      `/dedicated/server/${SERVER}/virtualMac/${m}/virtualAddress`
    ).catch(() => []);
    if (ips.includes(address)) return m;
  }
  return null;
}

/**
 * Claim a free IP for a server and create its OVH Virtual MAC so the VM can use it.
 * Returns the address + virtualMac + gateway, or null if none available.
 */
export async function allocateDedicatedIp(
  serverId: string,
  vmid: number
): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
  if (SANDBOX) {
    // Hand out a synthetic dedicated IP without any OVH call or pool mutation.
    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
  }
  // Idempotent per server: PROVISION can retry (up to MAX_ATTEMPTS). If this
  // server already holds a fully-allocated dedicated IP (ASSIGNED + a bound
  // Virtual MAC), return it instead of claiming a second pool IP — re-claiming
  // would leak an IP and P2002 on the unique DedicatedIp.serverId.
  const mine = await db.dedicatedIp.findUnique({ where: { serverId } });
  if (mine && mine.status === "ASSIGNED" && mine.virtualMac) {
    return { address: mine.address, virtualMac: mine.virtualMac, gateway: ovhGateway() };
  }
  if (!ovhConfigured()) return null;
  // Atomically claim a FREE ip
  const claim = await db.$transaction(async (tx) => {
    const ip = await tx.dedicatedIp.findFirst({ where: { status: "FREE" }, orderBy: { createdAt: "asc" } });
    if (!ip) return null;
    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
    return ip;
  });
  if (!claim) return null;

  try {
    // Reuse an existing vMAC for this IP if one is already bound; else create one.
    let mac = await findVirtualMacForIp(claim.address);
    if (!mac) {
      // Creation is asynchronous (returns a task) — kick it off then poll.
      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
      for (let i = 0; i < 40 && !mac; i++) {
        await new Promise((r) => setTimeout(r, 3000));
        mac = await findVirtualMacForIp(claim.address);
      }
    }
    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
    return { address: claim.address, virtualMac: mac, gateway: ovhGateway() };
  } catch (e) {
    // Roll the claim back to FREE on failure
    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
    throw e;
  }
}

/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual MAC). */
export async function releaseDedicatedIp(serverId: string): Promise<void> {
  if (SANDBOX) return;
  const ip = await db.dedicatedIp.findUnique({ where: { serverId } });
  if (!ip) return;
  if (ovhConfigured() && ip.virtualMac) {
    try {
      // Remove the IP from the vMAC, then delete the vMAC.
      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
    } catch {
      /* best-effort */
    }
  }
  await db.dedicatedIp.update({
    where: { id: ip.id },
    data: { status: "FREE", serverId: null, virtualMac: null },
  });
}

/** Set reverse DNS (PTR) for a dedicated IP. */
export async function setDedicatedReverse(address: string, reverse: string): Promise<void> {
  if (!ovhConfigured()) return;
  await ovhApi.setReverse(`${address}/32`, address, reverse);
  await db.dedicatedIp.updateMany({ where: { address }, data: { reverse } });
}
